q(288,"Medium","Which sentence uses the CORRECT homophone in a government context?",["The government vehicle must be ensured against damage.","The government vehicle must be assured against damage.","The government vehicle must be insured against damage.","The government vehicle must be insurrd against damage."],"The government vehicle must be insured against damage.","'Insure' means to provide financial insurance coverage. 'Ensure' makes something certain; 'assure' reassures a person.",["ensure-insure-assure","government-context"]),
q(289,"Medium","Which sentence uses the CORRECT homophone in a government context?",["The orientation will proceed the written examination.","The orientation will precede the written examination.","The orientation will preseed the written examination.","The orientation will procede the written examination."],"The orientation will precede the written examination.","'Precede' means to come before. 'Proceed' means to continue forward.",["precede-proceed","government-context"]),
q(290,"Medium","Which sentence uses the CORRECT homophone in a government context?",["Please precede to the next item on the agenda.","Please proceed to the next item on the agenda.","Please preseed to the next item on the agenda.","Please procede to the next item on the agenda."],"Please proceed to the next item on the agenda.","'Proceed' means to continue or move forward. 'Precede' means to come before.",["precede-proceed","government-context"]),
q(291,"Medium","Which sentence uses the CORRECT homophone in a government context?",["Their reports are due at the end of the month.","There reports are due at the end of the month.","They're reports are due at the end of the month.","Thier reports are due at the end of the month."],"Their reports are due at the end of the month.","'Their' is the possessive pronoun meaning belonging to them. 'There' indicates place; 'they're' = they are.",["their-there-theyre","government-context"]),
q(292,"Medium","Which sentence uses the CORRECT homophone in a government context?",["Their are three copies of the document on file.","There are three copies of the document on file.","They're are three copies of the document on file.","Thier are three copies of the document on file."],"There are three copies of the document on file.","'There' introduces a clause (There are...). 'Their' shows possession; 'they're' = they are.",["their-there-theyre","government-context"]),
q(293,"Medium","Which sentence uses the CORRECT homophone in a government context?",["The employees confirmed that their attending the seminar.","The employees confirmed that there attending the seminar.","The employees confirmed that they're attending the seminar.","The employees confirmed that thier attending the seminar."],"The employees confirmed that they're attending the seminar.","'They're' is the contraction of they are. 'Their' shows possession; 'there' indicates place.",["their-there-theyre","government-context"]),
q(294,"Medium","Which sentence uses the CORRECT homophone in a government context?",["The board past the resolution unanimously.","The board passed the resolution unanimously.","The board passd the resolution unanimously.","The board pased the resolution unanimously."],"The board passed the resolution unanimously.","'Passed' is the past tense of pass. 'Past' refers to a former time.",["passed-past","government-context"]),
q(295,"Medium","Which sentence uses the CORRECT homophone in a government context?",["In the passed, the agency used a manual filing system.","In the past, the agency used a manual filing system.","In the passd, the agency used a manual filing system.","In the pased, the agency used a manual filing system."],"In the past, the agency used a manual filing system.","'Past' refers to a former time. 'Passed' is the past tense of the verb pass.",["passed-past","government-context"]),
q(296,"Medium","Which sentence uses the CORRECT homophone in a government context?",["The weather delayed the field inspection.","The whether delayed the field inspection.","The wether delayed the field inspection.","The wheather delayed the field inspection."],"The weather delayed the field inspection.","'Weather' refers to atmospheric conditions. 'Whether' introduces alternatives.",["weather-whether","government-context"]),
q(297,"Medium","Which sentence uses the CORRECT homophone in a government context?",["Determine weather the claim is valid before proceeding.","Determine whether the claim is valid before proceeding.","Determine wether the claim is valid before proceeding.","Determine wheather the claim is valid before proceeding."],"Determine whether the claim is valid before proceeding.","'Whether' introduces alternatives or a conditional clause. 'Weather' refers to atmospheric conditions.",["weather-whether","government-context"]),
q(298,"Medium","Which sentence uses the CORRECT homophone in a government context?",["The weak argument was dismissed by the committee.","The week argument was dismissed by the committee.","The weake argument was dismissed by the committee.","The weke argument was dismissed by the committee."],"The weak argument was dismissed by the committee.","'Weak' means lacking strength. 'Week' is a period of seven days.",["weak-week","government-context"]),
q(299,"Medium","Which sentence uses the CORRECT homophone in a government context?",["Submit the report within one weak.","Submit the report within one week.","Submit the report within one weake.","Submit the report within one weke."],"Submit the report within one week.","'Week' is a period of seven days. 'Weak' means lacking strength.",["weak-week","government-context"]),
q(300,"Medium","Which sentence uses the CORRECT homophone in a government context?",["Do not waist government resources.","Do not waste government resources.","Do not wast government resources.","Do not waiste government resources."],"Do not waste government resources.","'Waste' means to use carelessly. 'Waist' is the middle part of the body.",["waste-waist","government-context"]),
